// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }

    function testFuzz_property(uint256 amount, address newOwner) public {
        // keep the funding amount in a wide but admissible domain (nonzero, sane)
        amount = bound(amount, 1 ether, 1_000_000 ether);
        // owner must be a plain EOA (no code) so the payable transfer succeeds
        vm.assume(newOwner != address(0));
        vm.assume(newOwner.code.length == 0);

        // fund the contract with a nonzero balance
        vm.deal(address(c), amount);
        assertTrue(address(c).balance > 0, "setup: balance funded");

        // deployer (this test contract) is the initial owner; hand ownership to a fuzzed EOA
        c.transferOwnership(newOwner);

        // drive c through withdraw as the (fuzzed) owner
        vm.prank(newOwner);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // GENERAL RULE: a successful withdraw() by the owner drains the whole contract balance to zero
        assertTrue(ok && address(c).balance == 0, "withdraw must drain full balance to zero");
    }
}
